import{z as i,x as B,o as t,c as p,q as s,j as A,D as E,d as r,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"WAL","description":"","frontmatter":{"title":"WAL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wal.md","filePath":"cs/wal.md","lastUpdated":1791413859000}'),d={name:"cs/wal.md"};function D(m,a,S,c,h,f){const l=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="wal" tabindex="-1">WAL <a class="header-anchor" href="#wal" aria-label="Permalink to &quot;WAL&quot;">​</a></h1><div class="epigraph"><p>先把变更写到顺序日志，再把脏页写回数据文件；崩溃时重放日志，而不是指望页已经落盘。</p><footer>—— 据 Gray and Reuter；Mohan et al. ARIES 对 WAL 协议的整理</footer></div><p><a href="/cs/hash-index">上一课</a>把等值访问路径收进桶页。索引与堆的页都会脏。<a href="/cs/buffer-dirty">缓冲与脏页</a>已经承认内存与磁盘可以不一致。缺口是：崩溃发生在脏页回写中途时，如何既不丢已提交更新，又不把未提交更新变成永久事实。WAL 给出写顺序：日志先于数据页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若先改数据页再记「做了什么」，崩溃会留下半新半旧的页，且无法重做。若每个提交都把所有脏页刷盘，吞吐打穿。缺口不是新的页格式，而是<strong>日志先行</strong>：变更以顺序记录追加到日志；提交成功至少意味着该事务的日志已持久；数据页可以迟写。</p><p>本课不把 ARIES 的补偿日志与脏页表写完，那是下一课。这里只钉协议：UNDO/REDO 信息进日志，LSN 单调，页上带 pageLSN。</p><p><span class="marginnote">LSN 翻译成大白话：日志的行号；pageLSN 是每页上贴的「我已应用到第几行」的便签。恢复时对照两处，就知道这页还差几条日志没补——不会重复应用，也不会漏应用。</span></p><p><span class="marginnote">强制：提交时刷哪些。窃取：未提交事务的脏页可否被换出。WAL 支持 steal/no-force，正是为了缓冲池自由调度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每次页修改：分配 LSN，写日志记录（旧值、新值或操作），再改缓冲中的页并打上 pageLSN。提交写 commit 记录并刷日志（至少到该 LSN）。检查点缩短恢复时必须扫描的日志前缀。本课假定单机、同一日志；分布式提交是后课两阶段提交。</p>',10)),(t(),A(n,null,{default:E(()=>[o(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E4%BF%AE%E6%94%B9%E9%A1%B5%22%5D%20--%3E%20LOG%5B%22%E5%85%88%E8%BF%BD%E5%8A%A0%E6%97%A5%E5%BF%97%22%5D%0A%20%20LOG%20--%3E%20PAGE%5B%22%E5%86%8D%E6%94%B9%E7%BC%93%E5%86%B2%E9%A1%B5%22%5D%0A%20%20LOG%20--%3E%20COMMIT%5B%22%E6%8F%90%E4%BA%A4%3A%20%E5%88%B7%E6%97%A5%E5%BF%97%22%5D%0A%20%20COMMIT%20--%3E%20ARIES%5B%22%E5%90%8E%E8%AF%BE%3A%20ARIES%20%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字直觉：普通 SSD 随机写大约每秒几万次，顺序写可达每秒几百 MB。把「每次提交把所有脏页刷盘」换成「追加一条日志记录」，吞吐相差两个数量级——这是 WAL 顺带赚到的性能红利。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"顺序写日志比随机写数据页便宜，这是性能理由；正确性理由是：有了完整日志，恢复可以 REDO 已提交、UNDO 未提交，即使数据页落后或超前。pageLSN 告诉恢复「这一页已经应用到哪条日志」，避免重复应用或漏应用——细节在 ARIES。",-1)),(t(),A(n,null,{default:E(()=>[o(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%E5%90%8E%E9%87%8D%E5%90%AF%22%5D%20--%3E%20SCAN%5B%22%E4%BB%8E%E6%9C%80%E8%BF%91%E6%A3%80%E6%9F%A5%E7%82%B9%E8%B5%B7%E6%89%AB%E6%97%A5%E5%BF%97%22%5D%0A%20%20SCAN%20--%3E%20Q%7B%22%E4%BA%8B%E5%8A%A1%E6%9C%89%20commit%20%E8%AE%B0%E5%BD%95%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%E6%9C%89%20--%3E%20REDO%5B%22REDO%3A%20%E9%87%8D%E6%94%BE%E5%8F%98%E6%9B%B4%E5%88%B0%E6%95%B0%E6%8D%AE%E9%A1%B5%22%5D%0A%20%20Q%20--%20%E6%97%A0%20--%3E%20UNDO%5B%22UNDO%3A%20%E6%8C%89%E6%97%A7%E5%80%BC%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20REDO%20--%3E%20OK%5B%22%E6%95%B0%E6%8D%AE%E9%A1%B5%E5%9B%9E%E5%88%B0%E4%B8%80%E8%87%B4%E7%8A%B6%E6%80%81%22%5D%0A%20%20UNDO%20--%3E%20OK%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>日志也是后课复制与逻辑解码的原料，本课只要求本地崩溃重启。同步刷日志的策略（组提交）把多次 fsync 合并，不改变「提交 ≤ 日志持久」这条不等式。</p><p><span class="marginnote">初学者容易以为提交后数据页就已落盘。WAL 的承诺恰恰弱得多：提交只保证日志持久，数据页可以几分钟后才写——只要日志在，崩溃后就能把页重放出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>WAL 不代替完整性约束，也不提供隔离：并发仍要锁或版本。不把文件系统 journal 与数据库 WAL 当成同一模块；库通常绕过 FS 缓存自己管。本课不讲逻辑日志与物理日志的全部混合设计，ARIES 用生理日志（页内物理、逻辑 UNDO）。</p><p>日志设备与数据盘分开，是为了顺序带宽不被随机页写打断，不是另一种正确性公理。后课默认：已提交事务的变更可经日志重做；未提交必须可撤销。怎么扫日志、如何处理崩溃时的补偿，下一课收。</p><p>没有 WAL，steal/no-force 会把未提交写进磁盘且无法撤。有了它，缓冲策略才从正确性里解放出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>索引页会脏；本课规定日志先于数据页，提交先于丢掉日志。</li><li>steal/no-force 让缓冲池与正确性解耦。</li><li>重启时 REDO/UNDO 的算法是 ARIES 的缺口。</li><li>出处：Gray and Reuter；Mohan et al., ARIES, TODS 1992。</li></ul>',8))])}const N=i(d,[["render",D]]);export{L as __pageData,N as default};
